window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c607cde76bb99f5d"]={"versions": [{"id": "FIG-c607cde76bb99f5d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) zur Laufzeitkonfiguration von Log-Levels im AUTOSAR-Basissoftwaremodul Diagnostic Log and Trace (DLT). Es stellt die vertikale und horizontale Schichtenarchitektur zwischen externem Diagnosetester, Diagnose-Kommunikationsmanager (DCM), DLT-Modul, Laufzeitumgebung (RTE) und einer Software-Komponente (SWC) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Externer Client / Diagnosetester</strong>: Symbolisiert durch Anwender und Laptop, sendet DLT-Steuernachrichten über UDS.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Entgegennahme der Diagnoseanforderung.\n</li><li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Modul, enthält intern eine Tabelle für Log-Level und Kontexte (<code>Level Context: xxx dddd, xxx dddd</code>) sowie das Submodul <strong>DLT comunication module</strong>.\n</li><li><strong>RTE (Real-Time Environment)</strong>: Vermittlungsschicht zwischen BSW und Applikationsebene.\n</li><li><strong>SWC (Software Component)</strong>: Anwendungs-Komponente mit internem Filter-/Entscheidungsmechanismus bezüglich Log-Nachrichten.\n</li><li><strong>Schnittstellen &amp; Interaktionen</strong>:\n<ul class=\"fig-list\"><li>UDS-Service <code>WriteDataByIdentifier</code> (Client an DCM).\n</li><li>C-API <code>Dlt_WriteData</code> (DCM an DLT).\n</li><li>Benachrichtigungsschnittstelle / Callback <code>Dlt_SetLogLevel</code> (DLT über RTE an SWC).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der nummerierte Ablauf gliedert sich in zwei nummerierte Ketten (violette Ziffern 1 bis 4 für die Konfigurationskette und türkise Ziffer 1 für die Filterung):</p>\n<ol class=\"fig-list\"><li>Ein externer Client sendet über UDS (<code>WriteDataByIdentifier</code>) DLT-Steuerbefehle zum Setzen von Log-Levels an das DCM (Schritt 1, violett).\n</li><li>Das DCM leitet die Konfigurationsdaten über die Schnittstelle <code>Dlt_WriteData</code> an das DLT-Modul weiter (Schritt 2, violett).\n</li><li>Das DLT-Modul verwaltet und aktualisiert die zulässigen Log-Levels für die jeweiligen Kontexte (<code>DLT administrate allowed log levels</code>, Schritt 3, violett).\n</li><li>Das DLT-Modul informiert die betroffene SWC über die RTE mittels <code>Dlt_SetLogLevel</code> über die geänderten Log-Levels (Schritt 4, violett).\n</li><li>Auf Basis des aktualisierten Log-Levels kann die SWC intern entscheiden, Log-Nachrichten zu unterdrücken bzw. nicht zu versenden (Schritt 1, türkis, visualisiert durch ein rotes Kreuz an einem internen Block).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht das Architekturmuster zur Entlastung des Gesamtsystems: Die dynamische Konfiguration der Log-Levels erfolgt über standardisierte UDS-Diagnosedienste, wird im DLT-Modul zentral administriert und an die Applikations-SWCs propagiert. Dies ermöglicht clientseitige Frühfilterung (Early Filtering) direkt in der SWC, wodurch unnötige RTE-Aufrufe und DLT-Pufferbelegungen zur Laufzeit vermieden werden.</p>"}, {"id": "FIG-302dd02b16f0159c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) zur Laufzeitkonfiguration von Log-Levels im AUTOSAR-Basissoftwaremodul Diagnostic Log and Trace (DLT). Es stellt die vertikale und horizontale Schichtenarchitektur zwischen externem Diagnosetester, Diagnose-Kommunikationsmanager (DCM), DLT-Modul, Laufzeitumgebung (RTE) und einer Software-Komponente (SWC) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Externer Client / Diagnosetester</strong>: Symbolisiert durch Anwender und Laptop, sendet DLT-Steuernachrichten über UDS.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Entgegennahme der Diagnoseanforderung.\n</li><li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Modul, enthält intern eine Tabelle für Log-Level und Kontexte (<code>Level Context: xxx dddd, xxx dddd</code>) sowie das Submodul <strong>DLT comunication module</strong>.\n</li><li><strong>RTE (Real-Time Environment)</strong>: Vermittlungsschicht zwischen BSW und Applikationsebene.\n</li><li><strong>SWC (Software Component)</strong>: Anwendungs-Komponente mit internem Filter-/Entscheidungsmechanismus bezüglich Log-Nachrichten.\n</li><li><strong>Schnittstellen &amp; Interaktionen</strong>:\n<ul class=\"fig-list\"><li>UDS-Service <code>WriteDataByIdentifier</code> (Client an DCM).\n</li><li>C-API <code>Dlt_WriteData</code> (DCM an DLT).\n</li><li>Benachrichtigungsschnittstelle / Callback <code>Dlt_SetLogLevel</code> (DLT über RTE an SWC).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der nummerierte Ablauf gliedert sich in zwei nummerierte Ketten (violette Ziffern 1 bis 4 für die Konfigurationskette und türkise Ziffer 1 für die Filterung):</p>\n<ol class=\"fig-list\"><li>Ein externer Client sendet über UDS (<code>WriteDataByIdentifier</code>) DLT-Steuerbefehle zum Setzen von Log-Levels an das DCM (Schritt 1, violett).\n</li><li>Das DCM leitet die Konfigurationsdaten über die Schnittstelle <code>Dlt_WriteData</code> an das DLT-Modul weiter (Schritt 2, violett).\n</li><li>Das DLT-Modul verwaltet und aktualisiert die zulässigen Log-Levels für die jeweiligen Kontexte (<code>DLT administrate allowed log levels</code>, Schritt 3, violett).\n</li><li>Das DLT-Modul informiert die betroffene SWC über die RTE mittels <code>Dlt_SetLogLevel</code> über die geänderten Log-Levels (Schritt 4, violett).\n</li><li>Auf Basis des aktualisierten Log-Levels kann die SWC intern entscheiden, Log-Nachrichten zu unterdrücken bzw. nicht zu versenden (Schritt 1, türkis, visualisiert durch ein rotes Kreuz an einem internen Block).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht das Architekturmuster zur Entlastung des Gesamtsystems: Die dynamische Konfiguration der Log-Levels erfolgt über standardisierte UDS-Diagnosedienste, wird im DLT-Modul zentral administriert und an die Applikations-SWCs propagiert. Dies ermöglicht clientseitige Frühfilterung (Early Filtering) direkt in der SWC, wodurch unnötige RTE-Aufrufe und DLT-Pufferbelegungen zur Laufzeit vermieden werden.</p>"}, {"id": "FIG-4a23127ba0061a0f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) zur Laufzeitkonfiguration von Log-Levels im AUTOSAR-Basissoftwaremodul Diagnostic Log and Trace (DLT). Es stellt die vertikale und horizontale Schichtenarchitektur zwischen externem Diagnosetester, Diagnose-Kommunikationsmanager (DCM), DLT-Modul, Laufzeitumgebung (RTE) und einer Software-Komponente (SWC) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Externer Client / Diagnosetester</strong>: Symbolisiert durch Anwender und Laptop, sendet DLT-Steuernachrichten über UDS.\n</li><li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Entgegennahme der Diagnoseanforderung.\n</li><li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Modul, enthält intern eine Tabelle für Log-Level und Kontexte (<code>Level Context: xxx dddd, xxx dddd</code>) sowie das Submodul <strong>DLT comunication module</strong>.\n</li><li><strong>RTE (Real-Time Environment)</strong>: Vermittlungsschicht zwischen BSW und Applikationsebene.\n</li><li><strong>SWC (Software Component)</strong>: Anwendungs-Komponente mit internem Filter-/Entscheidungsmechanismus bezüglich Log-Nachrichten.\n</li><li><strong>Schnittstellen &amp; Interaktionen</strong>:\n<ul class=\"fig-list\"><li>UDS-Service <code>WriteDataByIdentifier</code> (Client an DCM).\n</li><li>C-API <code>Dlt_WriteData</code> (DCM an DLT).\n</li><li>Benachrichtigungsschnittstelle / Callback <code>Dlt_SetLogLevel</code> (DLT über RTE an SWC).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der nummerierte Ablauf gliedert sich in zwei nummerierte Ketten (violette Ziffern 1 bis 4 für die Konfigurationskette und türkise Ziffer 1 für die Filterung):</p>\n<ol class=\"fig-list\"><li>Ein externer Client sendet über UDS (<code>WriteDataByIdentifier</code>) DLT-Steuerbefehle zum Setzen von Log-Levels an das DCM (Schritt 1, violett).\n</li><li>Das DCM leitet die Konfigurationsdaten über die Schnittstelle <code>Dlt_WriteData</code> an das DLT-Modul weiter (Schritt 2, violett).\n</li><li>Das DLT-Modul verwaltet und aktualisiert die zulässigen Log-Levels für die jeweiligen Kontexte (<code>DLT administrate allowed log levels</code>, Schritt 3, violett).\n</li><li>Das DLT-Modul informiert die betroffene SWC über die RTE mittels <code>Dlt_SetLogLevel</code> über die geänderten Log-Levels (Schritt 4, violett).\n</li><li>Auf Basis des aktualisierten Log-Levels kann die SWC intern entscheiden, Log-Nachrichten zu unterdrücken bzw. nicht zu versenden (Schritt 1, türkis, visualisiert durch ein rotes Kreuz an einem internen Block).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht das Architekturmuster zur Entlastung des Gesamtsystems: Die dynamische Konfiguration der Log-Levels erfolgt über standardisierte UDS-Diagnosedienste, wird im DLT-Modul zentral administriert und an die Applikations-SWCs propagiert. Dies ermöglicht clientseitige Frühfilterung (Early Filtering) direkt in der SWC, wodurch unnötige RTE-Aufrufe und DLT-Pufferbelegungen zur Laufzeit vermieden werden.</p>"}], "trans": [{"from": "FIG-c607cde76bb99f5d", "to": "FIG-302dd02b16f0159c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Gesamtgrafik wurde neu gerendert und minimal skaliert (Seitenverhältnis/Auflösung leicht angepasst).\n</li><li>Beschriftungen und Linien wurden mit geringfügigen Positions- und Schriftgrößen-Verschiebungen neu gerendert; inhaltlich blieben alle Funktionsbezeichner, Ablaufschritte und Entitäten identisch.\n</li></ul>"}, {"from": "FIG-302dd02b16f0159c", "to": "FIG-4a23127ba0061a0f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
